
// ADVANCED ACCIDENT ANALYSIS
// Results generated by Apache Spark

Chart.defaults.color = "#BCE9DE";
Chart.defaults.font.family =
    "'Playfair Display', Georgia, serif";

const colors = [
    "#54B7BE",
    "#BCE9DE",
    "#216B78",
    "#A88BFA",
    "#F48FB1",
    "#73D7C0",
    "#F6C177",
    "#7DA7F7"
];

const gridColor = "rgba(188,233,222,0.12)";

function makeChart(id, type, items, label) {

    new Chart(document.getElementById(id), {
        type: type,

        data: {
            labels: items.map(item => item.name),

            datasets: [{
                label: label,
                data: items.map(item => item.count),

                backgroundColor: colors,
                borderColor: "#54B7BE",
                borderWidth: type === "line" ? 3 : 1,
                tension: 0.35,
                fill: false,
                borderRadius: type === "bar" ? 6 : 0
            }]
        },

        options: {
            responsive: true,
            maintainAspectRatio: false,

            plugins: {
                legend: {
                    display: type === "pie" ||
                             type === "doughnut"
                }
            },

            scales: type === "pie" || type === "doughnut"
                ? {}
                : {
                    x: {
                        grid: { display: false },
                        ticks: { color: "#BCE9DE" }
                    },
                    y: {
                        beginAtZero: true,
                        grid: { color: gridColor },
                        ticks: {
                            color: "#BCE9DE",
                            precision: 0
                        }
                    }
                }
        }
    });
}


// 1. YEARLY TRENDS
makeChart(
    "yearChart",
    "line",
    analysisData.yearly,
    "Total Accidents"
);


// 2. HOURLY DISTRIBUTION
makeChart(
    "hourChart",
    "bar",
    analysisData.hourly,
    "Accidents by Hour"
);


// 3. ACCIDENT CAUSES
makeChart(
    "causeChart",
    "doughnut",
    analysisData.causes,
    "Accident Causes"
);


// 4. ROAD TYPES
makeChart(
    "roadChart",
    "bar",
    analysisData.road_types,
    "Accidents by Road Type"
);


// 5. DAY-WISE ACCIDENTS
const dayOrder = [
    "Monday", "Tuesday", "Wednesday",
    "Thursday", "Friday", "Saturday", "Sunday"
];

const orderedDays = [...analysisData.weekdays].sort(
    (a, b) =>
        dayOrder.indexOf(a.name) -
        dayOrder.indexOf(b.name)
);

makeChart(
    "dayChart",
    "bar",
    orderedDays,
    "Accidents by Day"
);


// 6. ROAD TYPE VS SEVERITY
const severityRows = analysisData.severity_by_road;

const roadTypes = [
    ...new Set(severityRows.map(row => row.road_type))
];

const severityLevels = [
    "minor", "major", "fatal"
];

const severityColors = [
    "#54B7BE",
    "#BCE9DE",
    "#F48FB1"
];

new Chart(document.getElementById("severityRoadChart"), {
    type: "bar",

    data: {
        labels: roadTypes,

        datasets: severityLevels.map((severity, index) => ({
            label: severity,
            backgroundColor: severityColors[index],

            data: roadTypes.map(road => {
                const match = severityRows.find(
                    row =>
                        row.road_type === road &&
                        row.severity === severity
                );

                return match ? match.count : 0;
            })
        }))
    },

    options: {
        responsive: true,
        maintainAspectRatio: false,

        scales: {
            x: {
                stacked: true,
                grid: { display: false }
            },

            y: {
                stacked: true,
                beginAtZero: true,
                grid: { color: gridColor }
            }
        },

        plugins: {
            legend: { position: "bottom" }
        }
    }
});
